const STORE_KEY = 'ledger';
const CATEGORIES = {
  expense: ['餐饮', '交通', '购物', '居住', '娱乐', '医疗', '教育', '其他'],
  income: ['工资', '奖金', '兼职', '投资', '红包', '其他']
};

const el = (role) => app.querySelector('[data-role="' + role + '"]');

const dateInput = el('date');
const typeExpense = el('type-expense');
const typeIncome = el('type-income');
const categorySelect = el('category');
const amountInput = el('amount');
const noteInput = el('note');
const formMessage = el('form-message');
const submitBtn = el('submit');
const resetBtn = el('reset');
const filterMonth = el('filter-month');
const listMessage = el('list-message');
const recordList = el('record-list');
const sumIncome = el('sum-income');
const sumExpense = el('sum-expense');
const sumBalance = el('sum-balance');
const summaryScope = el('summary-scope');

let state = { records: [], filter: 'all' };
let saving = false;

function pad2(n) {
  return String(n).padStart(2, '0');
}

function todayStr() {
  const d = new Date();
  return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate());
}

function monthOf(dateStr) {
  if (typeof dateStr !== 'string' || dateStr.length < 7) return '';
  return dateStr.slice(0, 7);
}

function isValidDate(dateStr) {
  if (typeof dateStr !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) return false;
  const parts = dateStr.split('-');
  const y = Number(parts[0]);
  const m = Number(parts[1]);
  const d = Number(parts[2]);
  if (m < 1 || m > 12 || d < 1 || d > 31) return false;
  const dt = new Date(y, m - 1, d);
  return dt.getFullYear() === y && dt.getMonth() === m - 1 && dt.getDate() === d;
}

function formatMoney(value) {
  const n = Number(value);
  const safe = Number.isFinite(n) ? n : 0;
  return '¥' + safe.toFixed(2);
}

function formatMonthLabel(month) {
  if (!month) return '未知月份';
  const parts = month.split('-');
  if (parts.length < 2) return month;
  return parts[0] + '年' + Number(parts[1]) + '月';
}

function normalizeRecord(raw) {
  if (!raw || typeof raw !== 'object') return null;
  const type = raw.type === 'income' ? 'income' : 'expense';
  const amount = Number(raw.amount);
  const date = typeof raw.date === 'string' ? raw.date : '';
  const id = typeof raw.id === 'string' && raw.id ? raw.id : 'r_' + Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
  const next = Object.assign({}, raw, {
    id: id,
    date: date,
    type: type,
    category: typeof raw.category === 'string' && raw.category ? raw.category : '其他',
    amount: Number.isFinite(amount) ? amount : 0,
    note: typeof raw.note === 'string' ? raw.note : ''
  });
  return next;
}

function seedRecords() {
  const now = new Date();
  const y = now.getFullYear();
  const m = now.getMonth() + 1;
  const cur = y + '-' + pad2(m);
  const prevDate = new Date(y, now.getMonth() - 1, 15);
  const prev = prevDate.getFullYear() + '-' + pad2(prevDate.getMonth() + 1);
  return [
    { id: 'seed_1', date: cur + '-05', type: 'income', category: '工资', amount: 8000, note: '本月工资' },
    { id: 'seed_2', date: cur + '-08', type: 'expense', category: '餐饮', amount: 42.5, note: '午餐' },
    { id: 'seed_3', date: cur + '-12', type: 'expense', category: '交通', amount: 120, note: '地铁月卡' },
    { id: 'seed_4', date: prev + '-20', type: 'expense', category: '购物', amount: 268, note: '日用品' }
  ];
}

function readState(raw) {
  const source = raw && typeof raw === 'object' ? raw : {};
  const bucket = source[STORE_KEY];
  let records;
  if (bucket && typeof bucket === 'object' && Array.isArray(bucket.records)) {
    records = bucket.records.map(normalizeRecord).filter(Boolean);
  } else {
    records = seedRecords().map(normalizeRecord).filter(Boolean);
  }
  let filter = 'all';
  if (bucket && typeof bucket === 'object' && typeof bucket.filter === 'string' && bucket.filter) {
    filter = bucket.filter;
  }
  return { records: records, filter: filter };
}

function buildNextState(records, filter) {
  return { [STORE_KEY]: { records: records, filter: filter } };
}

function sortedRecords(records) {
  return records.slice().sort((a, b) => {
    if (a.date === b.date) return 0;
    return a.date < b.date ? 1 : -1;
  });
}

function visibleRecords() {
  if (state.filter === 'all') return sortedRecords(state.records);
  return sortedRecords(state.records.filter((r) => monthOf(r.date) === state.filter));
}

function monthsInUse() {
  const set = new Set();
  state.records.forEach((r) => {
    const m = monthOf(r.date);
    if (m) set.add(m);
  });
  return Array.from(set).sort().reverse();
}

function renderCategoryOptions() {
  const type = typeIncome.checked ? 'income' : 'expense';
  const previous = categorySelect.value;
  const list = CATEGORIES[type];
  categorySelect.textContent = '';
  list.forEach((name) => {
    const opt = document.createElement('option');
    opt.value = name;
    opt.textContent = name;
    categorySelect.appendChild(opt);
  });
  if (list.indexOf(previous) !== -1) {
    categorySelect.value = previous;
  }
}

function renderFilterOptions() {
  const months = monthsInUse();
  const previous = state.filter;
  filterMonth.textContent = '';

  const allOpt = document.createElement('option');
  allOpt.value = 'all';
  allOpt.textContent = '全部月份';
  filterMonth.appendChild(allOpt);

  months.forEach((m) => {
    const opt = document.createElement('option');
    opt.value = m;
    opt.textContent = formatMonthLabel(m);
    filterMonth.appendChild(opt);
  });

  if (previous !== 'all' && months.indexOf(previous) === -1) {
    const opt = document.createElement('option');
    opt.value = previous;
    opt.textContent = formatMonthLabel(previous) + '（无记录）';
    filterMonth.appendChild(opt);
  }

  filterMonth.value = previous;
}

function renderSummary() {
  const rows = visibleRecords();
  let income = 0;
  let expense = 0;
  rows.forEach((r) => {
    if (r.type === 'income') income += r.amount;
    else expense += r.amount;
  });
  const balance = income - expense;

  sumIncome.textContent = formatMoney(income);
  sumExpense.textContent = formatMoney(expense);
  sumBalance.textContent = formatMoney(balance);
  sumBalance.classList.remove('positive', 'negative');
  if (balance > 0) sumBalance.classList.add('positive');
  else if (balance < 0) sumBalance.classList.add('negative');

  summaryScope.textContent = state.filter === 'all'
    ? '统计范围：全部记录（共 ' + rows.length + ' 笔）'
    : '统计范围：' + formatMonthLabel(state.filter) + '（共 ' + rows.length + ' 笔）';
}

function renderList() {
  const rows = visibleRecords();
  recordList.textContent = '';

  if (rows.length === 0) {
    const li = document.createElement('li');
    li.className = 'empty';
    li.textContent = state.filter === 'all'
      ? '还没有任何记录，先在上方添加一笔吧。'
      : formatMonthLabel(state.filter) + ' 没有记录。';
    recordList.appendChild(li);
    return;
  }

  rows.forEach((r) => {
    const li = document.createElement('li');
    li.className = 'record-item';

    const main = document.createElement('div');
    main.className = 'record-main';

    const top = document.createElement('div');
    top.className = 'record-top';

    const tag = document.createElement('span');
    tag.className = 'tag ' + (r.type === 'income' ? 'income' : 'expense');
    tag.textContent = r.type === 'income' ? '收入' : '支出';
    top.appendChild(tag);

    const cat = document.createElement('span');
    cat.className = 'record-category';
    cat.textContent = r.category;
    top.appendChild(cat);

    const amount = document.createElement('span');
    amount.className = 'record-amount ' + (r.type === 'income' ? 'income' : 'expense');
    amount.textContent = (r.type === 'income' ? '+' : '-') + formatMoney(r.amount);
    top.appendChild(amount);

    main.appendChild(top);

    const meta = document.createElement('div');
    meta.className = 'record-meta';
    const dateText = r.date || '未填写日期';
    meta.textContent = r.note ? dateText + ' · ' + r.note : dateText;
    main.appendChild(meta);

    li.appendChild(main);

    const del = document.createElement('button');
    del.type = 'button';
    del.className = 'btn danger';
    del.textContent = '删除';
    del.addEventListener('click', () => {
      handleDelete(r.id);
    });
    li.appendChild(del);

    recordList.appendChild(li);
  });
}

function renderAll() {
  renderFilterOptions();
  renderSummary();
  renderList();
}

function setFormMessage(text, kind) {
  formMessage.textContent = text || '';
  formMessage.className = 'form-message' + (kind ? ' ' + kind : '');
}

function setListMessage(text, kind) {
  listMessage.textContent = text || '';
  listMessage.className = 'list-message' + (kind ? ' ' + kind : '');
}

async function persist(records, filter) {
  const next = buildNextState(records, filter);
  await appStore.setState(next);
}

async function handleSubmit() {
  if (saving) return;

  const date = dateInput.value;
  const type = typeIncome.checked ? 'income' : 'expense';
  const category = categorySelect.value;
  const amountRaw = amountInput.value.trim();
  const note = noteInput.value.trim();

  if (!isValidDate(date)) {
    setFormMessage('请选择有效的日期。', 'error');
    return;
  }
  if (!category) {
    setFormMessage('请选择分类。', 'error');
    return;
  }
  const amount = Number(amountRaw);
  if (amountRaw === '' || !Number.isFinite(amount) || amount <= 0) {
    setFormMessage('请输入大于 0 的金额。', 'error');
    return;
  }
  const rounded = Math.round(amount * 100) / 100;

  const record = {
    id: 'r_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7),
    date: date,
    type: type,
    category: category,
    amount: rounded,
    note: note
  };

  const nextRecords = state.records.concat([record]);
  const nextFilter = state.filter;

  saving = true;
  submitBtn.disabled = true;
  setFormMessage('正在保存…', '');
  try {
    await persist(nextRecords, nextFilter);
  } catch (err) {
    saving = false;
    submitBtn.disabled = false;
    setFormMessage('保存失败，请重试。表单内容已保留。', 'error');
    return;
  }

  state = { records: nextRecords, filter: nextFilter };
  saving = false;
  submitBtn.disabled = false;

  amountInput.value = '';
  noteInput.value = '';
  setFormMessage('已保存：' + (type === 'income' ? '收入' : '支出') + ' ' + formatMoney(rounded) + ' · ' + category, 'ok');
  renderAll();
}

async function handleDelete(id) {
  if (saving) return;
  const target = state.records.find((r) => r.id === id);
  if (!target) return;

  const label = (target.type === 'income' ? '收入' : '支出') + ' ' + formatMoney(target.amount) + ' · ' + target.category + ' · ' + (target.date || '未填写日期');
  const confirmed = window.confirm('确定删除这条记录吗？\n' + label + '\n删除后无法恢复。');
  if (!confirmed) return;

  const nextRecords = state.records.filter((r) => r.id !== id);
  const nextFilter = state.filter;

  saving = true;
  setListMessage('正在删除…', '');
  try {
    await persist(nextRecords, nextFilter);
  } catch (err) {
    saving = false;
    setListMessage('删除失败，请重试。记录仍然保留。', 'error');
    return;
  }

  state = { records: nextRecords, filter: nextFilter };
  saving = false;
  setListMessage('已删除该记录。', 'ok');
  renderAll();
}

async function handleFilterChange() {
  const value = filterMonth.value || 'all';
  const previous = state.filter;
  if (value === previous) return;

  try {
    await persist(state.records, value);
  } catch (err) {
    filterMonth.value = previous;
    setListMessage('筛选条件保存失败，请重试。', 'error');
    return;
  }

  state = { records: state.records, filter: value };
  setListMessage('', '');
  renderAll();
}

function handleReset() {
  dateInput.value = todayStr();
  typeExpense.checked = true;
  typeIncome.checked = false;
  renderCategoryOptions();
  amountInput.value = '';
  noteInput.value = '';
  setFormMessage('表单已清空。', '');
}

function bindEvents() {
  submitBtn.addEventListener('click', () => {
    handleSubmit();
  });

  resetBtn.addEventListener('click', () => {
    handleReset();
  });

  typeExpense.addEventListener('change', () => {
    if (typeExpense.checked) renderCategoryOptions();
  });
  typeIncome.addEventListener('change', () => {
    if (typeIncome.checked) renderCategoryOptions();
  });

  filterMonth.addEventListener('change', () => {
    handleFilterChange();
  });

  amountInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleSubmit();
    }
  });
  noteInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleSubmit();
    }
  });
}

async function main() {
  const raw = await appStore.getState();
  state = readState(raw);

  dateInput.value = todayStr();
  renderCategoryOptions();
  bindEvents();
  renderAll();

  const bucket = raw && typeof raw === 'object' ? raw[STORE_KEY] : null;
  const hasBucket = bucket && typeof bucket === 'object' && Array.isArray(bucket.records);
  if (!hasBucket) {
    try {
      await persist(state.records, state.filter);
    } catch (err) {
      setFormMessage('初始化示例数据失败，可手动添加记录。', 'error');
    }
  }
}

await main();

artifact.css:
:root {
  --bg: #f4f6fb;
  --card: #ffffff;
  --text: #1f2937;
  --muted: #6b7280;
  --line: #e5e7eb;
  --primary: #2563eb;
  --primary-dark: #1d4ed8;
  --income: #15803d;
  --expense: #dc2626;
  --danger: #b91c1c;
  --radius: 12px;
}

* {
  box-sizing: border-box;
}

.page {
  max-width: 720px;
  margin: 0 auto;
  padding: 20px 16px 48px;
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  font-size: 15px;
  line-height: 1.5;
}

.app-header h1 {
  margin: 0 0 4px;
  font-size: 24px;
}

.subtitle {
  margin: 0 0 18px;
  color: var(--muted);
  font-size: 13px;
}

.card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 16px;
  margin-bottom: 16px;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
}

.card-title {
  margin: 0 0 12px;
  font-size: 16px;
}

.summary-card {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  text-align: center;
}

.summary-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 6px 4px;
}

.summary-label {
  font-size: 12px;
  color: var(--muted);
}

.summary-value {
  font-size: 18px;
  font-weight: 700;
  word-break: break-all;
}

.summary-value.income {
  color: var(--income);
}

.summary-value.expense {
  color: var(--expense);
}

.summary-value.balance.negative {
  color: var(--expense);
}

.summary-value.balance.positive {
  color: var(--income);
}

.summary-scope {
  grid-column: 1 / -1;
  margin: 4px 0 0;
  font-size: 12px;
  color: var(--muted);
  text-align: center;
}

.field {
  margin-bottom: 12px;
}

.field > label,
.type-field > legend {
  display: block;
  margin-bottom: 6px;
  font-size: 13px;
  font-weight: 600;
  color: #374151;
}

.type-field {
  border: 0;
  padding: 0;
  margin: 0 0 12px;
}

input[type="date"],
input[type="number"],
input[type="text"],
select {
  width: 100%;
  padding: 9px 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
  color: var(--text);
  font-size: 15px;
  font-family: inherit;
}

input:focus,
select:focus {
  outline: 2px solid rgba(37, 99, 235, 0.35);
  outline-offset: 1px;
  border-color: var(--primary);
}

.radio-row {
  display: flex;
  gap: 16px;
}

.radio-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 14px;
  cursor: pointer;
}

.form-message,
.list-message {
  margin: 0 0 10px;
  font-size: 13px;
  min-height: 18px;
}

.form-message.error,
.list-message.error {
  color: var(--danger);
}

.form-message.ok {
  color: var(--income);
}

.actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.btn {
  padding: 9px 16px;
  border-radius: 8px;
  border: 1px solid transparent;
  font-size: 14px;
  font-family: inherit;
  cursor: pointer;
}

.btn.primary {
  background: var(--primary);
  color: #fff;
}

.btn.primary:hover {
  background: var(--primary-dark);
}

.btn.ghost {
  background: #fff;
  border-color: var(--line);
  color: #374151;
}

.btn.ghost:hover {
  background: #f9fafb;
}

.btn.danger {
  background: #fff;
  border-color: #fecaca;
  color: var(--danger);
}

.btn.danger:hover {
  background: #fef2f2;
}

.btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.list-head {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 10px;
}

.list-head .card-title {
  margin: 0;
}

.filter-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.filter-row label {
  font-size: 13px;
  font-weight: 600;
  color: #374151;
  white-space: nowrap;
}

.filter-row select {
  width: auto;
  min-width: 140px;
}

.record-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.record-item {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px 0;
  border-top: 1px solid var(--line);
}

.record-item:first-child {
  border-top: 0;
}

.record-main {
  flex: 1 1 auto;
  min-width: 0;
}

.record-top {
  display: flex;
  align-items: baseline;
  gap: 8px;
  flex-wrap: wrap;
}

.record-category {
  font-weight: 600;
}

.record-amount {
  font-weight: 700;
  margin-left: auto;
  white-space: nowrap;
}

.record-amount.income {
  color: var(--income);
}

.record-amount.expense {
  color: var(--expense);
}

.record-meta {
  margin-top: 2px;
  font-size: 12px;
  color: var(--muted);
  word-break: break-word;
}

.tag {
  display: inline-block;
  padding: 1px 7px;
  border-radius: 999px;
  font-size: 11px;
  border: 1px solid var(--line);
  color: var(--muted);
}

.tag.income {
  border-color: #bbf7d0;
  background: #f0fdf4;
  color: var(--income);
}

.tag.expense {
  border-color: #fecaca;
  background: #fef2f2;
  color: var(--expense);
}

.empty {
  padding: 18px 4px;
  text-align: center;
  color: var(--muted);
  font-size: 14px;
}

@media (max-width: 480px) {
  .summary-value {
    font-size: 16px;
  }

  .list-head {
    align-items: stretch;
  }

  .filter-row {
    justify-content: space-between;
  }

  .filter-row select {
    flex: 1 1 auto;
  }
}
